const BREADCRUMBS_STATES: &[StateDoc] = &[
    StateDoc {
        state: "Current",
        selector: ".breadcrumbs__link[data-current=\"true\"]",
        description: "The last crumb is the current page: it renders in the link token, is not a tab stop, answers no press even with an href, and never takes the disabled fade.",
        rust: "is_last -> colors.link + no tab stop + no on_click",
        status: ImplementationStatus::Implemented,
    },
    StateDoc {
        state: "Hover",
        selector: ".breadcrumbs__link:hover / [data-hovered=\"true\"]",
        description: "Link crumbs underline on hover; the colour stays muted.",
        rust: "hover(|s| s.underline()) when navigable",
        status: ImplementationStatus::Implemented,
    },
    StateDoc {
        state: "Focus",
        selector: "[data-focus-visible=\"true\"]",
        description: "Every link crumb is a tab stop (React Aria link semantics) and draws the focus-visible status ring when keyboard-focused; mouse focus leaves the ring off. Enter and Space activate the focused crumb through gpui's focused-click, so no second key handler is bound. The current page and disabled crumbs are not tab stops at all.",
        rust: "tab_stop_handle per link crumb + ring_if_focused + gpui focused-click",
        status: ImplementationStatus::Implemented,
    },
    StateDoc {
        state: "Disabled",
        selector: "aria-disabled=\"true\"",
        description: "isDisabled disables every link: none takes a press, none stays a tab stop, and all of them fade — except the current page, which [data-current] holds at opacity-100.",
        rust: "is_disabled -> disabled_opacity when !is_last + focus gated on !disabled",
        status: ImplementationStatus::Implemented,
    },
];

